import { createHash } from "node:crypto";

/** The only reference shapes that may be persisted in a checkpoint attachment. */
export const CHECKPOINT_ATTACHMENT_REFERENCE_KINDS = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
] as const;

export type CheckpointAttachmentReferenceKind =
  (typeof CHECKPOINT_ATTACHMENT_REFERENCE_KINDS)[number];

export type CheckpointAttachmentBindingState =
  | "recovered"
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "expired"
  | "conflict"
  | "invalid-kind"
  | "invalid-ref";

export interface CheckpointAttachmentBinding {
  attachmentRef: string;
  kind: CheckpointAttachmentReferenceKind;
  contentHash: string;
  owner: string;
  /** Absolute Unix time in milliseconds after which the binding is invalid. */
  ttl: number;
}

export interface RecoverableCheckpointAttachmentBinding {
  attachmentRef: string;
  kind: CheckpointAttachmentReferenceKind;
  contentHash: string;
  owner: string;
  ttl: number;
}

export interface CheckpointAttachmentBindingStatus {
  attachmentRef: string;
  kind?: CheckpointAttachmentReferenceKind;
  contentHash?: string;
  owner?: string;
  ttl?: number;
  state: CheckpointAttachmentBindingState;
  reason: string;
}

export interface CheckpointAttachmentRecoveryResult {
  recovered: RecoverableCheckpointAttachmentBinding[];
  statuses: CheckpointAttachmentBindingStatus[];
  digest: string;
}

const SHA256_HEX = /^[0-9a-f]{64}$/i;
const REFERENCE_KIND_SET = new Set<string>(CHECKPOINT_ATTACHMENT_REFERENCE_KINDS);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`)
    .join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareRecovered(
  left: RecoverableCheckpointAttachmentBinding,
  right: RecoverableCheckpointAttachmentBinding,
): number {
  return (
    compareText(left.attachmentRef, right.attachmentRef) ||
    compareText(left.contentHash, right.contentHash) ||
    compareText(left.kind, right.kind) ||
    compareText(left.owner, right.owner) ||
    left.ttl - right.ttl
  );
}

/**
 * Validate and recover persisted attachment references without mutating the input.
 * `now` is an explicit clock value so recovery remains deterministic and side-effect free.
 */
export function recoverCheckpointAttachmentBindings(
  bindings: readonly unknown[],
  now: number = Date.now(),
): CheckpointAttachmentRecoveryResult {
  if (!Array.isArray(bindings)) {
    throw new TypeError("bindings must be an array");
  }
  if (!Number.isFinite(now)) {
    throw new TypeError("now must be a finite number");
  }

  const statuses: CheckpointAttachmentBindingStatus[] = [];
  const recovered: RecoverableCheckpointAttachmentBinding[] = [];
  const firstHashByRef = new Map<string, string>();

  for (const candidate of bindings) {
    if (!isRecord(candidate)) {
      statuses.push({
        attachmentRef: "",
        state: "invalid-ref",
        reason: "binding must be an object",
      });
      continue;
    }

    const attachmentRef = candidate.attachmentRef;
    const kind = candidate.kind;
    const contentHash = candidate.contentHash;
    const owner = candidate.owner;
    const ttl = candidate.ttl;

    if (!nonEmptyString(attachmentRef)) {
      statuses.push({
        state: "invalid-ref",
        reason: "attachmentRef must be a non-empty string",
      });
      continue;
    }

    if (!nonEmptyString(kind) || !REFERENCE_KIND_SET.has(kind)) {
      statuses.push({
        attachmentRef,
        state: "invalid-kind",
        reason: `kind must be one of: ${CHECKPOINT_ATTACHMENT_REFERENCE_KINDS.join(", ")}`,
      });
      continue;
    }

    const normalizedKind = kind as CheckpointAttachmentReferenceKind;

    if (typeof contentHash !== "string" || contentHash.trim().length === 0) {
      statuses.push({
        attachmentRef,
        kind: normalizedKind,
        owner: nonEmptyString(owner) ? owner : undefined,
        ttl: typeof ttl === "number" ? ttl : undefined,
        state: "missing-hash",
        reason: "contentHash is required",
      });
      continue;
    }

    if (!SHA256_HEX.test(contentHash)) {
      statuses.push({
        attachmentRef,
        kind: normalizedKind,
        contentHash,
        owner: nonEmptyString(owner) ? owner : undefined,
        ttl: typeof ttl === "number" ? ttl : undefined,
        state: "invalid-hash",
        reason: "contentHash must be a SHA-256 hexadecimal digest",
      });
      continue;
    }

    const normalizedHash = contentHash.toLowerCase();
    const knownHash = firstHashByRef.get(attachmentRef);
    if (knownHash !== undefined) {
      if (knownHash === normalizedHash) {
        statuses.push({
          attachmentRef,
          kind: normalizedKind,
          contentHash: normalizedHash,
          owner: nonEmptyString(owner) ? owner : undefined,
          ttl: typeof ttl === "number" ? ttl : undefined,
          state: "recovered",
          reason: "duplicate reference and hash was deduplicated",
        });
      } else {
        statuses.push({
          attachmentRef,
          kind: normalizedKind,
          contentHash: normalizedHash,
          owner: nonEmptyString(owner) ? owner : undefined,
          ttl: typeof ttl === "number" ? ttl : undefined,
          state: "conflict",
          reason: `attachmentRef already refers to hash ${knownHash}`,
        });
      }
      continue;
    }

    if (!nonEmptyString(owner)) {
      statuses.push({
        attachmentRef,
        kind: normalizedKind,
        contentHash: normalizedHash,
        ttl: typeof ttl === "number" ? ttl : undefined,
        state: "missing-owner",
        reason: "owner is required",
      });
      continue;
    }

    if (typeof ttl !== "number" || !Number.isFinite(ttl)) {
      statuses.push({
        attachmentRef,
        kind: normalizedKind,
        contentHash: normalizedHash,
        owner,
        state: "expired",
        reason: "ttl must be an absolute Unix time in milliseconds",
      });
      continue;
    }

    if (ttl <= now) {
      statuses.push({
        attachmentRef,
        kind: normalizedKind,
        contentHash: normalizedHash,
        owner,
        ttl,
        state: "expired",
        reason: "binding TTL has expired",
      });
      continue;
    }

    firstHashByRef.set(attachmentRef, normalizedHash);
    const binding: RecoverableCheckpointAttachmentBinding = {
      attachmentRef,
      kind: normalizedKind,
      contentHash: normalizedHash,
      owner,
      ttl,
    };
    recovered.push(binding);
    statuses.push({
      attachmentRef,
      kind: normalizedKind,
      contentHash: normalizedHash,
      owner,
      ttl,
      state: "recovered",
      reason: "binding is valid",
    });
  }

  recovered.sort(compareRecovered);
  statuses.sort((left, right) => {
    const leftRef = left.attachmentRef;
    const rightRef = right.attachmentRef;
    return (
      compareText(leftRef, rightRef) ||
      compareText(left.state, right.state) ||
      compareText(left.contentHash ?? "", right.contentHash ?? "") ||
      compareText(left.reason, right.reason)
    );
  });

  const digest = sha256(canonicalJson({ recovered, statuses }));
  return { recovered, statuses, digest };
}

export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;

export function checkpointAttachmentBindingDigest(
  result: Pick<CheckpointAttachmentRecoveryResult, "recovered" | "statuses">,
): string {
  return sha256(canonicalJson(result));
}

